insert into public.perks
  (id, slug, name, category, tagline, description, products, website_url, logo_url, cover_image_url, is_featured, sort_order)
values
  ('1f7a1a59-e00e-4384-b6bb-35bf0290c122', 'cleartax', 'ClearTax', 'Tax & Compliance', 'GST, e-invoicing and income tax filing', 'Indian tax compliance platform covering GST returns, e-invoicing and e-way bills, and income tax and TDS filing. Includes a GST package built for CAs and tax experts.', array['GST filing', 'E-invoicing', 'Income tax & TDS', 'ClearTax for CAs']::text[], 'https://cleartax.in', 'perks/logos/cleartax.svg', 'perks/covers/cleartax.jpg', true, 10),
  ('bffe16a9-4c16-4b9d-8f4d-6305e28cdcdd', 'avalara', 'Avalara', 'Tax & Compliance', 'Automated indirect tax compliance', 'Calculates sales tax, VAT and GST in real time and handles returns filing, e-invoicing and exemption certificates. Integrates with QuickBooks and major ERPs.', array['AvaTax', 'Returns filing', 'E-invoicing', 'Exemption certificates']::text[], 'https://www.avalara.com', 'perks/logos/avalara.png', 'perks/covers/avalara.jpg', false, 20),
  ('6d9d54ff-45f4-4f65-8827-6413fc77b1b9', 'tallyprime', 'TallyPrime', 'Accounting & Audit', 'Accounting and GST software for Indian businesses', 'Accounting, GST invoicing, inventory, payroll and statutory reporting on desktop and cloud, used by Indian CAs and accountants for client books.', array['TallyPrime', 'Tally on Cloud', 'GST compliance', 'Connected banking']::text[], 'https://tallysolutions.com', 'perks/logos/tallyprime.png', 'perks/covers/tallyprime.jpg', true, 30),
  ('3cfe5280-09ad-4678-8478-e78d69e3739d', 'zoho-books', 'Zoho Books', 'Accounting & Audit', 'Cloud accounting for growing businesses', 'Online accounting with invoicing, GST-ready compliance, inventory and bank reconciliation. Zoho runs a program for accountants who advise clients on Zoho Books.', array['Accounting', 'GST compliance', 'Inventory', 'Bank reconciliation']::text[], 'https://www.zoho.com/books/', 'perks/logos/zoho-books.png', 'perks/covers/zoho-books.jpg', false, 40),
  ('f4ea675c-c62c-4b87-8cf5-bd6458ff6070', 'xero', 'Xero', 'Accounting & Audit', 'Online accounting and practice tools', 'Cloud accounting platform with bank feeds, invoicing and reporting. The Xero partner program gives accountants and bookkeepers tools to manage client books.', array['Xero Accounting', 'Practice Manager', 'Xero Tax', 'Advisor tools']::text[], 'https://www.xero.com', 'perks/logos/xero.png', 'perks/covers/xero.jpg', false, 50),
  ('0a8fde79-601b-4905-9dcd-aad3c99ddb9d', 'quickbooks', 'QuickBooks', 'Accounting & Audit', 'Accounting software from Intuit', 'Cloud accounting, invoicing, expense tracking and payroll, widely used by accounting firms for client bookkeeping.', array['QuickBooks Online', 'Payroll', 'Payments', 'ProAdvisor program']::text[], 'https://quickbooks.intuit.com', 'perks/logos/quickbooks.png', 'perks/covers/quickbooks.jpg', false, 60),
  ('149a6506-8ab9-4455-89e9-8f2bcc0d0f1d', 'caseware', 'CaseWare', 'Accounting & Audit', 'Audit and financial reporting software', 'Working paper, financial statement and data analytics tools used by audit and accounting firms worldwide.', array['CaseWare Cloud', 'Working Papers', 'IDEA analytics', 'Financial reporting']::text[], 'https://www.caseware.com', 'perks/logos/caseware.png', 'perks/covers/caseware.jpg', false, 70),
  ('c0516c96-2292-4724-a415-c66536e4cdc4', 'mindbridge', 'MindBridge', 'Accounting & Audit', 'AI risk discovery for audit and finance', 'Analyses general ledger and transaction data with AI to flag unusual entries and risk for auditors and finance teams.', array['Ai Auditor', 'Anomaly detection', 'Risk scoring']::text[], 'https://www.mindbridge.ai', 'perks/logos/mindbridge.png', 'perks/covers/mindbridge.jpg', false, 80),
  ('9563124a-200d-47fe-aaaf-62f46ccf81aa', 'diligent', 'Diligent', 'Corporate Secretarial', 'Governance, risk and compliance software', 'Board portal and entity management software for governance, minutes and statutory records.', array['Diligent Boards', 'Entities', 'Minutes', 'Compliance']::text[], 'https://www.diligent.com', 'perks/logos/diligent.png', 'perks/covers/diligent.jpg', false, 90),
  ('207fb4ae-a7b2-41d7-9359-1735d9468e03', 'carta', 'Carta', 'Corporate Secretarial', 'Equity and entity management', 'Cap table, equity plans (ESOPs), valuations and fund administration for startups and investors.', array['Cap table', 'Equity plans', 'Valuations', 'Fund admin']::text[], 'https://carta.com', 'perks/logos/carta.png', 'perks/covers/carta.jpg', false, 100),
  ('8a432fbc-bb06-43ef-a413-8eaccfb7b18e', 'scc-online', 'SCC Online', 'Legal', 'Indian case law and statutes', 'Indian legal research database of case law, statutes and law reports, used by chambers and firms.', array['Case law', 'Statutes', 'Law reports', 'Legal research']::text[], 'https://www.scconline.com', 'perks/logos/scc-online.png', 'perks/covers/scc-online.jpg', false, 110),
  ('e00a9f13-26fd-4bae-ac2c-a26e2bfaa57e', 'casemine', 'CaseMine', 'Legal', 'AI-powered legal research', 'Indian case law research with AI search and case analysis tools.', array['Case law search', 'AMICUS', 'AI research']::text[], 'https://www.casemine.com', 'perks/logos/casemine.png', 'perks/covers/casemine.jpg', false, 120),
  ('7ea0f588-f45d-4c65-97da-e01a8906caf6', 'spellbook', 'Spellbook', 'Legal', 'AI contract drafting in Word', 'AI assistant inside Microsoft Word for drafting and reviewing contracts.', array['Contract drafting', 'Contract review', 'Word add-in']::text[], 'https://www.spellbook.com', 'perks/logos/spellbook.png', 'perks/covers/spellbook.jpg', false, 130),
  ('99dd2422-766a-42b5-8112-56f793d30b5e', 'clio', 'Clio', 'Legal', 'Legal practice management', 'Case management, client intake, billing and document drafting for law firms.', array['Clio Manage', 'Clio Grow', 'Clio Draft']::text[], 'https://www.clio.com', 'perks/logos/clio.png', 'perks/covers/clio.jpg', false, 140),
  ('47f53ed1-3124-46a6-9516-368c2816e52c', 'docusign', 'DocuSign', 'Legal', 'E-signature and agreement management', 'Sign, send and manage agreements digitally, from simple e-signature to full contract lifecycle management.', array['eSignature', 'Contract lifecycle management', 'Maestro workflows']::text[], 'https://www.docusign.com', 'perks/logos/docusign.png', 'perks/covers/docusign.jpg', false, 150),
  ('2714fb09-b441-40a7-ab63-2abccc7f41e0', 'chatgpt', 'ChatGPT', 'AI Tools', 'OpenAI''s AI assistant', 'General AI assistant for research, drafting, analysis and custom workflows. Business plans add admin controls and data protections for teams.', array['ChatGPT Business', 'Deep research', 'Custom GPTs']::text[], 'https://chatgpt.com', 'perks/logos/chatgpt.png', 'perks/covers/chatgpt.jpg', true, 160),
  ('97bbd2e7-becd-42bc-90ba-7b89108239c3', 'claude', 'Claude', 'AI Tools', 'Anthropic''s AI assistant', 'AI assistant for long-document analysis, writing and research, with team workspaces and shared projects.', array['Claude Team', 'Projects', 'Research']::text[], 'https://claude.ai', 'perks/logos/claude.png', 'perks/covers/claude.jpg', false, 170),
  ('be22077c-a078-4901-91e3-d08240353bbf', 'perplexity', 'Perplexity', 'AI Tools', 'AI search that cites its sources', 'Answer engine that shows sources for every answer, with a Deep Research mode and enterprise plans.', array['Perplexity Pro', 'Deep Research', 'Enterprise Pro']::text[], 'https://www.perplexity.ai', 'perks/logos/perplexity.png', 'perks/covers/perplexity.jpg', false, 180),
  ('c9a88a76-c4cc-4f9b-9956-6e90952c890f', 'fireflies-ai', 'Fireflies.ai', 'AI Tools', 'AI notes for client calls', 'Records, transcribes and summarises calls and meetings, with searchable notes and action items.', array['Transcription', 'Meeting summaries', 'Action items']::text[], 'https://fireflies.ai', 'perks/logos/fireflies-ai.png', 'perks/covers/fireflies-ai.jpg', false, 190),
  ('636ab5f3-9967-41ed-81c3-5240044d1f58', 'taxdome', 'TaxDome', 'Practice & Productivity', 'All-in-one practice management', 'Client portal, CRM, workflows, e-signatures and billing built for accounting and tax firms.', array['Client portal', 'Workflows', 'E-signatures', 'Billing']::text[], 'https://taxdome.com', 'perks/logos/taxdome.png', 'perks/covers/taxdome.jpg', false, 200),
  ('0f96281d-5047-465d-ac30-bd980e6a7fd1', 'notion', 'Notion', 'Practice & Productivity', 'Connected workspace for docs and projects', 'Docs, wikis and projects in one workspace, with Notion AI for drafting and search.', array['Notion', 'Notion AI', 'Notion Calendar']::text[], 'https://www.notion.so', 'perks/logos/notion.png', 'perks/covers/notion.jpg', false, 210)
insert into public.learnings
  (id, title, summary, video_provider, video_url, thumbnail_url, channel, duration_minutes, category, level, audiences, is_featured, sort_order)
values
  ('104e13b0-5483-481b-abe9-18d104b32fd2', 'AI Agents, Clearly Explained', 'Agents are what turn a chatbot into something that does a task end to end. This is the plain-English picture before you pick any tool.', 'youtube', 'https://www.youtube.com/watch?v=FwOTs4UxQS4', 'learnings/thumbnails/104e13b0-5483-481b-abe9-18d104b32fd2.jpg', 'Jeff Su', 10, 'AI essentials', 'beginner', array['tax', 'legal', 'audit']::text[], true, 10),
  ('8f64e284-f5e4-4669-8bf0-091612b861b4', 'Claude AI Tutorial for Beginners', 'A calm first walk-through of one of the main AI assistants. Good for anyone who has only tried ChatGPT so far.', 'youtube', 'https://www.youtube.com/watch?v=r2vYObllqJU', 'learnings/thumbnails/8f64e284-f5e4-4669-8bf0-091612b861b4.jpg', 'Kevin Stratvert', 9, 'AI essentials', 'beginner', array['tax', 'legal', 'audit']::text[], false, 20),
  ('5b067d2a-a234-47d1-a02c-80d2ba828577', 'Google''s 9-Hour AI Prompt Engineering Course in 20 Minutes', 'Better prompts are the cheapest upgrade you can make. This condenses a full course into one sitting.', 'youtube', 'https://www.youtube.com/watch?v=p09yRj47kNM', 'learnings/thumbnails/5b067d2a-a234-47d1-a02c-80d2ba828577.jpg', 'Tina Huang', 20, 'AI essentials', 'beginner', array['tax', 'legal', 'audit']::text[], false, 30),
  ('b8e8cd25-694e-4a35-baa8-2bce4d7eb6ac', 'Learn 80% of NotebookLM in Under 13 Minutes', 'Load circulars, judgments or standards as sources and ask questions against them. Useful for research-heavy work.', 'youtube', 'https://www.youtube.com/watch?v=EOmgC3-hznM', 'learnings/thumbnails/b8e8cd25-694e-4a35-baa8-2bce4d7eb6ac.jpg', 'Jeff Su', 13, 'AI essentials', 'beginner', array['tax', 'legal', 'audit']::text[], false, 40),
  ('a8b37de3-9066-47e2-8561-713a0aac1dc4', 'ChatGPT Secrets for Lawyers', 'A short, practical start for lawyers who want to see what a good legal prompt looks like.', 'youtube', 'https://www.youtube.com/watch?v=lvkqaK4tRaU', 'learnings/thumbnails/a8b37de3-9066-47e2-8561-713a0aac1dc4.jpg', 'Sam Mollaei, Esq.', 9, 'Legal & drafting', 'beginner', array['legal']::text[], false, 50),
  ('862402b7-41b8-4441-8b50-928bb613b95a', 'ChatGPT for Lawyers: What It Does Well (And What It Doesn''t)', 'Know the limits before you put AI near client work. Watch this one before the drafting videos.', 'youtube', 'https://www.youtube.com/watch?v=GL9HLNRGyNI', 'learnings/thumbnails/862402b7-41b8-4441-8b50-928bb613b95a.jpg', 'Liam Barnes', 23, 'Legal & drafting', 'beginner', array['legal']::text[], false, 60),
  ('cf6fb985-7880-48fc-a294-82956f7c1c45', 'ChatGPT for Legal Drafting: A Step-by-Step Guide', 'A full drafting walk-through from an Indian advocate, so the examples sit closer to the work you do.', 'youtube', 'https://www.youtube.com/watch?v=5fiLC0rpY5s', 'learnings/thumbnails/cf6fb985-7880-48fc-a294-82956f7c1c45.jpg', 'Adv Nishant Bharihoke', 30, 'Legal & drafting', 'intermediate', array['legal']::text[], false, 70),
  ('7858cb48-7fd6-4f4e-b99f-37d82b75309c', 'Claude for Lawyers: Every Feature You Should Know', 'Projects, documents and long-context review, shown for legal use. Helps when contracts run long.', 'youtube', 'https://www.youtube.com/watch?v=83JGBJ6at2I', 'learnings/thumbnails/7858cb48-7fd6-4f4e-b99f-37d82b75309c.jpg', 'Liam Barnes', 19, 'Legal & drafting', 'intermediate', array['legal']::text[], false, 80),
  ('24f83fe4-518c-490b-9513-84fda7166837', '5 Best AI Tools for Chartered Accountants', 'Five minutes, from an ICAI session. A quick map of the tools worth trying first.', 'youtube', 'https://www.youtube.com/watch?v=OVfu7MZn1kA', 'learnings/thumbnails/24f83fe4-518c-490b-9513-84fda7166837.jpg', 'ICAI CA Tube', 5, 'Tax & accounting', 'beginner', array['tax', 'audit']::text[], false, 90),
  ('f4ee51df-7a59-4b44-bdca-0a521d145b2b', '5 AI Tools Every Accountant & CA Must Use in 2026', 'Tax and GST automation tools, grouped by the job they do, so you can match them to your practice.', 'youtube', 'https://www.youtube.com/watch?v=xXm61BGkS2c', 'learnings/thumbnails/f4ee51df-7a59-4b44-bdca-0a521d145b2b.jpg', 'FinTaxPro', 13, 'Tax & accounting', 'beginner', array['tax', 'audit']::text[], false, 100),
  ('c852bd40-f50e-4a99-b901-ca46620c8ce3', 'How to Automate GST Reconciliation with AI', 'GSTR-2A/2B matching is the monthly grind most practices share. See how much of it can be handed off.', 'youtube', 'https://www.youtube.com/watch?v=G_QBPExJSbo', 'learnings/thumbnails/c852bd40-f50e-4a99-b901-ca46620c8ce3.jpg', 'CA Tushar Makkar', 12, 'Tax & accounting', 'intermediate', array['tax']::text[], false, 110),
  ('db2119ac-b462-4ae4-9b18-7d560e869d1b', 'Generative AI''s Role in the Internal Audit Function', 'How a Big Four firm frames GenAI for internal audit. Useful vocabulary for client conversations.', 'youtube', 'https://www.youtube.com/watch?v=abkyxPN5e6I', 'learnings/thumbnails/db2119ac-b462-4ae4-9b18-7d560e869d1b.jpg', 'KPMG US', 7, 'Audit & assurance', 'beginner', array['audit']::text[], false, 120),
  ('779386f7-0b77-49fa-afc2-b8e4648648f7', 'AI-Powered Tax Audit Using Claude & MCP Server (Live Tally Demo)', 'A full live demo connecting an AI model to Tally data. Long, but it shows where this is heading.', 'youtube', 'https://www.youtube.com/watch?v=8AOKggscU7c', 'learnings/thumbnails/779386f7-0b77-49fa-afc2-b8e4648648f7.jpg', 'The Compliance CA', 68, 'Audit & assurance', 'advanced', array['audit', 'tax']::text[], false, 130),
  ('3f632e0c-e78e-4883-8d30-0775286990a2', 'Webinar: Tax Audit with AI, Practical Use Cases', 'A two-hour ICAI webinar on faster, more accurate compliance. Save it and watch it in parts.', 'youtube', 'https://www.youtube.com/watch?v=vxgUD8tg9j0', 'learnings/thumbnails/3f632e0c-e78e-4883-8d30-0775286990a2.jpg', 'ICAI CA Tube', 132, 'Audit & assurance', 'advanced', array['audit', 'tax']::text[], false, 140),
  ('36aaea7f-7bf0-4328-8ad0-e15a96ca70de', 'Copilot Excel Tutorial: Excel''s Biggest Upgrade Ever', 'Formulas, cleaning and summaries by asking in plain language. A direct time saver for reconciliations.', 'youtube', 'https://www.youtube.com/watch?v=KXqR6VuPBlk', 'learnings/thumbnails/36aaea7f-7bf0-4328-8ad0-e15a96ca70de.jpg', 'Kevin Stratvert', 16, 'Excel & decks', 'beginner', array['tax', 'audit']::text[], false, 150),
  ('0a062cdd-eb60-431b-a4da-d7a8ab681be5', 'Master Data Analysis with ChatGPT in 12 Minutes', 'Upload a sheet, ask questions, get charts. Handy for a first pass over a client ledger.', 'youtube', 'https://www.youtube.com/watch?v=FKLr3ft8ea0', 'learnings/thumbnails/0a062cdd-eb60-431b-a4da-d7a8ab681be5.jpg', 'Jeff Su', 12, 'Excel & decks', 'intermediate', array['tax', 'audit']::text[], false, 160),
  ('0e59e033-ac60-45ec-9e30-ebfcafc79a2b', 'PowerPoint Copilot Tutorial: How Microsoft''s New AI Changes Everything', 'Turn a memo or a Word document into a first-draft deck, then edit instead of starting blank.', 'youtube', 'https://www.youtube.com/watch?v=Yq6JlVrs-IU', 'learnings/thumbnails/0e59e033-ac60-45ec-9e30-ebfcafc79a2b.jpg', 'Kevin Stratvert', 9, 'Excel & decks', 'beginner', array['tax', 'legal', 'audit']::text[], false, 170),
  ('f2f3a77b-b1c5-48c6-8072-bc03312c18bf', 'n8n Tutorial for Beginners: Build AI Automations for Free', 'The basic building blocks of workflow automation. No code, and free to try.', 'youtube', 'https://www.youtube.com/watch?v=Fy1UCBcgF2o', 'learnings/thumbnails/f2f3a77b-b1c5-48c6-8072-bc03312c18bf.jpg', 'Charlie Chang', 19, 'Automation', 'intermediate', array['tax', 'legal', 'audit']::text[], false, 180),
  ('a9125f30-8ca1-41fb-82bd-7cc7baf50847', 'Automate Invoice Entry with n8n + Tally', 'A concrete accounting workflow: invoices in, Tally entries out. Good proof that automation fits a small practice.', 'youtube', 'https://www.youtube.com/watch?v=s1hgeDf_xnY', 'learnings/thumbnails/a9125f30-8ca1-41fb-82bd-7cc7baf50847.jpg', 'Pratik Joshi', 16, 'Automation', 'intermediate', array['tax']::text[], false, 190),
  ('5a6b7446-81b2-4d15-a159-d48782e319b2', 'DPDP Rules 2025 Explained: What It Means for Your Data & Privacy', 'Client data is what you hold. Know what the new rules mean before you paste any of it into an AI tool.', 'youtube', 'https://www.youtube.com/watch?v=I0z1pF2W-Sg', 'learnings/thumbnails/5a6b7446-81b2-4d15-a159-d48782e319b2.jpg', 'Vajiram & Ravi', 15, 'Data & privacy', 'beginner', array['tax', 'legal', 'audit']::text[], false, 200)
