  ('d91e6a70-c0e3-4e9e-b0d0-9e171c137c23', 'learning_playlist', 'ai-starter-kit', 'AI starter kit', 'The four videos every professional should watch first.', array['tax', 'legal', 'audit']::text[], array['104e13b0-5483-481b-abe9-18d104b32fd2', '8f64e284-f5e4-4669-8bf0-091612b861b4', '5b067d2a-a234-47d1-a02c-80d2ba828577', 'b8e8cd25-694e-4a35-baa8-2bce4d7eb6ac']::uuid[], 10),
