  ('57f9ae63-a70e-453e-98b3-cbb8da102939', 'learning_playlist', 'the-ai-ready-ca', 'The AI-ready CA', 'Tools, GST reconciliation and Excel, in the order they pay off.', array['tax']::text[], array['24f83fe4-518c-490b-9513-84fda7166837', 'f4ee51df-7a59-4b44-bdca-0a521d145b2b', 'c852bd40-f50e-4a99-b901-ca46620c8ce3', '36aaea7f-7bf0-4328-8ad0-e15a96ca70de']::uuid[], 30),
  ('b63629a6-40d7-4051-8374-08c8f38f0146', 'learning_playlist', 'audit-with-ai', 'Audit with AI', 'From the Big Four view to a live tax-audit demo.', array['audit']::text[], array['db2119ac-b462-4ae4-9b18-7d560e869d1b', '0a062cdd-eb60-431b-a4da-d7a8ab681be5', '779386f7-0b77-49fa-afc2-b8e4648648f7', '3f632e0c-e78e-4883-8d30-0775286990a2']::uuid[], 40),
  ('5c09e00f-82c1-4ea6-be51-90e2946dd56d', 'learning_playlist', 'automate-the-boring-work', 'Automate the boring work', 'Build your first workflows and stay on the right side of privacy rules.', array['tax', 'legal', 'audit']::text[], array['f2f3a77b-b1c5-48c6-8072-bc03312c18bf', 'a9125f30-8ca1-41fb-82bd-7cc7baf50847', '5a6b7446-81b2-4d15-a159-d48782e319b2']::uuid[], 50),
  ('6821e04d-b115-433b-8b08-6bba7d732983', 'perk_stack', 'solo-ca-practice', 'Solo CA practice', 'File GST and income tax, keep client books and run your practice from one place.', '{}'::text[], array['6d9d54ff-45f4-4f65-8827-6413fc77b1b9', '1f7a1a59-e00e-4384-b6bb-35bf0290c122', '636ab5f3-9967-41ed-81c3-5240044d1f58']::uuid[], 10),
  ('175a48d2-713d-4853-871b-1e8ed6ce2347', 'perk_stack', 'boutique-law-firm', 'Boutique law firm', 'Research Indian case law, draft faster and get agreements signed.', '{}'::text[], array['8a432fbc-bb06-43ef-a413-8eaccfb7b18e', '7ea0f588-f45d-4c65-97da-e01a8906caf6', '99dd2422-766a-42b5-8112-56f793d30b5e', '47f53ed1-3124-46a6-9516-368c2816e52c']::uuid[], 20),
  ('a318878c-efc7-4a81-8463-09a1671b93d1', 'perk_stack', 'audit-team', 'Audit team', 'Build workpapers and flag unusual entries before partner review.', '{}'::text[], array['149a6506-8ab9-4455-89e9-8f2bcc0d0f1d', 'c0516c96-2292-4724-a415-c66536e4cdc4', '97bbd2e7-becd-42bc-90ba-7b89108239c3']::uuid[], 30),
  ('21f6474e-befe-46c0-9889-8fecc9448119', 'perk_stack', 'startup-finance-and-cs', 'Startup finance and CS', 'Books, cap table and board records for a growing company.', '{}'::text[], array['3cfe5280-09ad-4678-8478-e78d69e3739d', '207fb4ae-a7b2-41d7-9359-1735d9468e03', '9563124a-200d-47fe-aaaf-62f46ccf81aa', '47f53ed1-3124-46a6-9516-368c2816e52c']::uuid[], 40),
  ('4301812e-2741-4dbb-8328-9751536585f5', 'perk_stack', 'ai-first-practice', 'AI-first practice', 'Research, summarise and capture knowledge with AI.', '{}'::text[], array['97bbd2e7-becd-42bc-90ba-7b89108239c3', 'be22077c-a078-4901-91e3-d08240353bbf', 'c9a88a76-c4cc-4f9b-9956-6e90952c890f', '0f96281d-5047-465d-ac30-bd980e6a7fd1']::uuid[], 50)
